// Gather every loop pass of the reconcile node and keep only people whose tier is overdue today.
const byEmail = {};
let run = 0;
while (run < 1000) {
  let items = null;
  try {
    items = $('Compute Chase Tier And Gaps').all(0, run);
  } catch (e) {
    break;
  }
  if (!items) break;
  for (const it of items) {
    const j = it.json || {};
    if (j.is_overdue && j.email && !byEmail[j.email]) byEmail[j.email] = j;
  }
  run = run + 1;
}
const overdue = Object.values(byEmail);
if (overdue.length === 0) {
  return [];
}
const lines = overdue.map(function (p) {
  return '- ' + String(p.name || 'Unknown') + ' (' + p.email + '): ' + String(p.missing_now || 'gaps not listed');
});
const text = 'Paperwork chase: ' + overdue.length + ' person(s) overdue today.\n' + lines.join('\n') + '\nChase emails went out on the overdue cadence. This is the daily roll up.';
return [{ json: { escalation_text: text, overdue_count: overdue.length } }];

// One roster row per loop pass. Reconcile the intake folder against the matrix and score the cadence.
const person = $('Loop People One by One').first().json;
const matrixRows = $('Fetch Requirement Matrix').all().map(function (i) { return i.json; });
const templates = $('List Blank Form Templates').all().map(function (i) { return i.json; }).filter(function (t) { return t && t.id && t.name; });

const files = $input.all().map(function (i) { return i.json; }).filter(function (f) { return f && f.name; });
const fileNames = files.map(function (f) { return String(f.name).toLowerCase(); });

const personRole = String(person.role || '').toLowerCase();
const required = matrixRows.filter(function (r) { return String(r.role || '').toLowerCase() === personRole; });

const today = $today;
const startDate = DateTime.fromISO(String(person.start_date || ''));

// Case insensitive, extension agnostic match: the uploaded file name only has to contain the slug.
const missing = [];
for (const req of required) {
  const slug = String(req.doc_slug || '').toLowerCase();
  if (!slug) continue;
  const have = fileNames.some(function (n) { return n.includes(slug); });
  if (have) continue;
  const offset = Number(req.due_offset_days) || 0;
  const due = startDate.isValid ? startDate.plus({ days: offset }) : today;
  const daysLeft = Math.floor(due.diff(today, 'days').days);
  missing.push({ slug: slug, label: String(req.doc_label || req.doc_slug), due_date: due.toISODate(), days_left: daysLeft });
}

const isComplete = required.length > 0 && missing.length === 0;

// Tier by the most urgent missing document.
let stage = 'waiting';
if (isComplete) {
  stage = 'complete';
} else if (missing.some(function (m) { return m.days_left < 0; })) {
  stage = 'overdue';
} else if (missing.some(function (m) { return m.days_left <= 2; })) {
  stage = 'firm';
} else if (missing.some(function (m) { return m.days_left <= 7; })) {
  stage = 'gentle';
}

// last_chased suppresses repeat emails inside each cadence window.
const cooldown = { gentle: 3, firm: 2, overdue: 1 };
let shouldChase = stage === 'gentle' || stage === 'firm' || stage === 'overdue';
if (shouldChase && person.last_chased) {
  const lastChased = DateTime.fromISO(String(person.last_chased));
  if (lastChased.isValid) {
    const daysSince = Math.floor(today.diff(lastChased.startOf('day'), 'days').days);
    if (daysSince < cooldown[stage]) shouldChase = false;
  }
}

// One blank form template per missing document, matched by slug substring on the template file name.
const matchedTemplates = [];
if (shouldChase) {
  for (const m of missing) {
    const t = templates.find(function (tp) { return String(tp.name).toLowerCase().includes(m.slug); });
    if (t && !matchedTemplates.some(function (x) { return x.id === t.id; })) {
      matchedTemplates.push({ id: t.id, name: t.name });
    }
  }
}

const firstName = String(person.name || '').trim().split(' ')[0] || 'there';
const itemLines = missing.map(function (m) {
  const tail = m.days_left < 0 ? Math.abs(m.days_left) + ' day(s) overdue' : 'due ' + m.due_date;
  return '- ' + m.label + ' (' + tail + ')';
}).join('\n');

let subject = '';
let body = '';
if (stage === 'gentle') {
  subject = 'Quick reminder: a few onboarding documents to send in';
  body = 'Hi ' + firstName + ',\n\nWelcome aboard! A quick heads up that we are still waiting on the following documents:\n\n' + itemLines + '\n\nBlank copies of the forms are attached. Just drop the completed files into your intake folder whenever you have a moment.\n\nThanks!';
} else if (stage === 'firm') {
  subject = 'Action needed: onboarding documents due soon';
  body = 'Hi ' + firstName + ',\n\nThe following documents are due within the next two days:\n\n' + itemLines + '\n\nBlank copies are attached. Please upload the completed files to your intake folder so everything is ready on time.\n\nThank you!';
} else {
  subject = 'Overdue: onboarding documents outstanding';
  body = 'Hi ' + firstName + ',\n\nThe following documents are now overdue:\n\n' + itemLines + '\n\nBlank copies are attached. Please upload the completed files to your intake folder today, or reply to this email if something is blocking you.\n\nThank you!';
}

const base = {
  name: person.name,
  email: person.email,
  role: person.role,
  start_date: person.start_date,
  drive_folder_id: person.drive_folder_id,
  is_complete: isComplete,
  should_chase: shouldChase,
  chase_stage: stage,
  new_last_chased: shouldChase ? today.toISODate() : String(person.last_chased || ''),
  missing_count: missing.length,
  missing_now: missing.map(function (m) { return m.slug + ' (due ' + m.due_date + ')'; }).join(', '),
  is_overdue: stage === 'overdue',
  subject: subject,
  email_body: body
};

if (!shouldChase || matchedTemplates.length === 0) {
  return [{ json: Object.assign({}, base, { template_file_id: '', template_file_name: '' }) }];
}
return matchedTemplates.map(function (t) {
  return { json: Object.assign({}, base, { template_file_id: t.id, template_file_name: t.name }) };
});

// Consolidate every downloaded blank form into ONE item with form_0, form_1 style binary properties.
const meta = $('Compute Chase Tier And Gaps').first().json;
const out = { json: { send_to: meta.email, subject: meta.subject, email_body: meta.email_body, attachment_props: '' }, binary: {} };
const props = [];
let idx = 0;
for (const item of $input.all()) {
  if (!item.binary) continue;
  for (const key of Object.keys(item.binary)) {
    const prop = 'form_' + idx;
    out.binary[prop] = item.binary[key];
    props.push(prop);
    idx = idx + 1;
  }
}
if (props.length === 0) {
  // No blank form matched in the templates folder. Attach a plain checklist so the chase still lands.
  const checklist = 'Missing documents for ' + String(meta.name || '') + '\n\n' + String(meta.missing_now || '') + '\n\nPlease upload the completed files to your intake folder.';
  out.binary.form_0 = {
    data: Buffer.from(checklist, 'utf8').toString('base64'),
    mimeType: 'text/plain',
    fileName: 'missing-documents.txt'
  };
  props.push('form_0');
}
out.json.attachment_props = props.join(',');
return [out];
